    seeds = [(r, c, g[r][c]) for r in range(R) for c in range(C)
             if g[r][c] != bg and (r, c) not in bar_cells]
    if not seeds:
        return g
    fill = seeds[0][2]
    seed_positions = {(r, c) for r, c, _ in seeds}

    # Bars project alternating parallel lines inward.
    for r, a, b in bars:
        dr = 1 if r == 0 else -1
        for c in range(a, b + 1):
            if (c - a) % 2:
                continue
            y = r + dr
            while 0 <= y < R:
                if (y, c) in seed_positions:
                    g[y][c] = 4
                    break
                g[y][c] = fill
                y += dr

    # Each isolated marker also projects along its column to the nearest
    # boundary bar, marked with endpoint color 4.
